SELECT cdscode
FROM frpm
WHERE (COALESCE("Enrollment (K-12)",0) + COALESCE("Enrollment (Ages 5-17)",0)) > 500;

SELECT CAST(SUM(CASE WHEN status = 'C' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS pct_running_ok
FROM loan
WHERE amount < 100000;

SELECT a.frequency
FROM account a
WHERE a.account_id = 3;

SELECT CAST(SUM(CASE WHEN m.molecule_id NOT IN (
    SELECT DISTINCT a.molecule_id FROM atom a WHERE a.element = 'f'
) THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(m.molecule_id) AS pct_no_fluorine
FROM molecule m
WHERE m.label = '+';

SELECT CAST(SUM(CASE WHEN element = 'h' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(atom_id) AS percentage
FROM atom
WHERE molecule_id = 'TR206';

SELECT COUNT(*) AS total_atoms
FROM atom a
WHERE a.element IN ('p','br')
  AND a.molecule_id IN (
    SELECT DISTINCT molecule_id FROM bond WHERE bond_type = '#'
  );

SELECT EXISTS (
  SELECT 1
  FROM cards c
  JOIN set_translations st ON c.setcode = st.setcode
  WHERE c.name = 'Ancestor''s Chosen' AND st.language = 'Korean'
) AS has_korean_version;

WITH most_influential AS (
  SELECT id FROM users ORDER BY reputation DESC LIMIT 1
)
SELECT CAST(SUM(CASE WHEN p.score > 50 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(p.id) AS percentage
FROM posts p
JOIN most_influential m ON p.owneruserid = m.id;

SELECT DISTINCT team_fifa_api_id
FROM team_attributes
WHERE buildupplayspeed > 50 AND buildupplayspeed < 60;

SELECT CAST(SUM(CASE WHEN admission = '-' THEN 1 ELSE 0 END) AS REAL) / NULLIF(SUM(CASE WHEN admission = '+' THEN 1 ELSE 0 END), 0) AS outpatient_to_inpatient_ratio
FROM patient
WHERE diagnosis = 'SLE';

SELECT CAST(SUM(CASE WHEN sex = 'F' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(sex)
FROM patient
WHERE EXTRACT(YEAR FROM birthday) = 1980 AND diagnosis = 'RA';

SELECT CAST(SUM(CASE WHEN segment = 'Premium' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS pct_premium
FROM gasstations
WHERE country = 'SVK';
